/**
 * The seeded layout of the sticker crowd behind iteration 2.
 *
 * The stickers themselves are cut-out PNGs of famous buildings in
 * public/stickers/, generated by scripts/generate-stickers.mjs from the list in
 * landmarks.ts. This module only decides where each one goes. The page
 * (src/components/crowd.tsx) and the share card (src/app/opengraph-image.tsx)
 * both read it, so they show the same crowd.
 */
import { LANDMARK_SLUGS } from './landmarks';

export type Placement = {
  name: string;
  /** Centre, in field units. */
  x: number;
  y: number;
  /** Degrees. */
  rot: number;
  /** Multiplier on the 100-unit sticker box. */
  scale: number;
  /** Drawn in front of the card rather than behind it. */
  front: boolean;
};

// Mulberry32: small, seeded, good enough for a layout.
function rng(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Field units. Tuned against the desktop card so the row below it just clips the edge. */
const ROW_SHIFT = 60;

export type CrowdOptions = {
  width: number;
  height: number;
  cols: number;
  rows: number;
  seed?: number;
  /** Which stickers to use; defaults to every landmark. */
  names?: string[];
  /**
   * The card's half-size in field units, measured from the field's centre. Stickers
   * in a band just outside it are candidates for the front layer, so they overlap
   * the card's edges and never its text.
   */
  cardHalf?: { x: number; y: number };
};

/**
 * A brick-offset, jittered grid, so the crowd is even but never lines up and no
 * white shows through. Each cell gets a sticker not seen within two cells, and the
 * draw order runs top to bottom so the sticker below always covers the one above.
 */
export function layoutCrowd({
  width,
  height,
  cols,
  rows,
  seed = 7,
  names = LANDMARK_SLUGS,
  cardHalf,
}: CrowdOptions): Placement[] {
  const random = rng(seed);
  const cw = width / cols;
  const ch = height / rows;
  const grid: string[][] = [];
  const out: Placement[] = [];

  for (let r = 0; r < rows; r++) {
    grid[r] = [];
    for (let c = 0; c < cols; c++) {
      // No repeat within two cells in any direction, so the same sticker is
      // never seen twice at a glance.
      const near = new Set<string>();
      for (let dr = -2; dr <= 0; dr++) {
        for (let dc = -2; dc <= 2; dc++) {
          const n = grid[r + dr]?.[c + dc];
          if (n) near.add(n);
        }
      }
      let name: string;
      let tries = 0;
      do {
        name = names[Math.floor(random() * names.length)];
      } while (near.has(name) && ++tries < 40);
      grid[r][c] = name;

      // Rows are offset by half a cell, like bricks, so the gaps between
      // stickers in one row are covered by the row below.
      const x = c * cw + cw / 2 + (r % 2 ? cw / 2 : 0) + (random() - 0.5) * cw * 0.2;
      // No vertical jitter: each row sits cleanly over the row above, so the
      // bottom edge of every sticker is hidden by the row below, like shingles.
      // Rows are shifted so the one just under the card clips its bottom edge.
      const y = r * ch + ch / 2 + ROW_SHIFT;
      const rot = (random() - 0.5) * 20;
      // About twice the row pitch tall, so each row covers half of the one above.
      const scale = 2.6 + random() * 0.2;

      let front = false;
      if (cardHalf) {
        const dx = Math.abs(x - width / 2);
        const dy = Math.abs(y - height / 2);
        // The sticker's centre sits on or just outside the edge, so at most half
        // of it (about the card's padding) lies over the card. The bottom edge
        // gets extra clearance: the teaser link sits close to it.
        // Only along the card's bottom edge, and only the sticker's top: a
        // sticker just below the card whose top reaches a little way over the
        // edge (never as far as the words). Everywhere else the crowd stays behind.
        const half = 50 * scale;
        const dyBelow = y - height / 2;
        // 1.1: a rotated sticker's box is a little taller than its scale.
        const clip = cardHalf.y - (dyBelow - half * 1.1);
        // Every sticker in that row that touches the edge, across the card's full
        // width, so hovering any of them lifts it above the card.
        front = dyBelow > cardHalf.y && clip > 0 && clip <= 90 && dx < cardHalf.x + half;
      }

      out.push({ name, x, y, rot, scale, front });
    }
  }

  // Draw order: top of the screen first, bottom last. A sticker lower on the
  // screen is in front, so its top covers the bottom of the one above it, the way
  // a crowd reads in a photograph.
  out.sort((a, b) => a.y - b.y);
  return out;
}
